global_rules.Standard output schema:
{
  "objective_id": "string",
  "status": "NEEDS_INPUT | NEEDS_RESEARCH | IN_PROGRESS | COMPLETE",
  "stage": "UNDERSTAND | PLAN | STRATEGY | READINESS | PROCEED",
  "ui": [
    {
      "component": "one approved primitive",
      "id": "stable string",
      "purpose": "string",
      "prompt": "string",
      "required": "boolean",
      "options": "array when relevant"
    }
  ],
  "confirmed_inputs": "object containing only user-confirmed facts",
  "derived_signals": [
    {
      "signal": "string",
      "basis": "string",
      "confidence": "LOW | MEDIUM | HIGH"
    }
  ],
  "unknowns": [
    "string"
  ],
  "result": {
    "summary": "string",
    "items": "array/object appropriate to objective"
  },
  "readiness": {
    "enabled": "boolean",
    "name": "string or null",
    "score": "0-100 or null",
    "dimensions": [
      {
        "name": "string",
        "score": "0-100",
        "reason": "string"
      }
    ],
    "blockers": [
      "string"
    ]
  },
  "next_actions": [
    {
      "id": "string",
      "label": "string",
      "type": "CONTINUE_CHAT | OPEN_OBJECTIVE | RESEARCH | COMPARE | LEARN | NAVIGATE | REQUEST_ACTION"
    }
  ],
  "handoff": {
    "summary": "string",
    "confirmed_user_inputs": "object",
    "result": "object",
    "evidence_and_unknowns": [
      "string"
    ],
    "recommended_next_action": "string"
  }
}
